function HeaderMenuEntries({items,parentId=null,go,depth=0}){return <>{items.filter(item=>(item.parentId||null)===parentId).map(item=>{const children=items.some(child=>child.parentId===item.id);return <div className={'navMenuEntry '+(children?'hasChildren':'')} key={item.id||`${item.label}-${item.url}`}><a href={item.url} target={item.openNewTab?'_blank':undefined} rel={item.openNewTab?'noopener noreferrer':undefined} className={(depth===0?'':'subNavLink')+(item.label==='AI Lab'?' labNav':'')} onClick={item.url.startsWith('/')?event=>go(event,item.url):undefined}><NavIcon name={item.iconKey||item.label}/><span>{item.label}</span>{children&&<small>⌄</small>}</a>{children&&<div className="navSubmenu"><HeaderMenuEntries items={items} parentId={item.id} go={go} depth={depth+1}/></div>}</div>})}</>}
function Header({lightsOn,onToggle,onStudio,navigate,navigation=[],locale,onLocaleToggle,user}){const [query,setQuery]=useState('');const [menuOpen,setMenuOpen]=useState(false);const go=(event,to)=>{event.preventDefault();setMenuOpen(false);navigate(to)};const items=navigation.filter(item=>item.location==='header');const menuItems=items.length?items:nav.map(([,label,url])=>({label,url,iconKey:label,openNewTab:false,parentId:null}));return <header className="siteHeader"><div className="wrap nav"><a className="brandAnchor" href="/" onClick={event=>go(event,'/')} aria-label="猫子的世界首页"><span className="desktopBrand"><Logo/></span><span className="mobileBrand"><Logo/></span></a><span className="brandDivider"/><nav className={'primaryNav '+(menuOpen?'mobileOpen':'')}><HeaderMenuEntries items={menuItems} go={go}/></nav><div className="navActions"><form className="search navSearch" onSubmit={event=>{event.preventDefault();navigate(`/posts?q=${encodeURIComponent(query.trim())}`)}}><Search size={16}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="搜索文章、标签、问题..." aria-label="搜索文章、标签、问题"/><kbd>⌘ K</kbd></form><button className="localeButton" onClick={onLocaleToggle} aria-label="切换中文和英文" title={locale==='zh-CN'?'Switch to English':'切换为中文'}><Languages size={17}/></button><button className="sun themeButton" onClick={onToggle} aria-label={lightsOn?'关闭灯光':'打开灯光'}>{lightsOn?<Sun size={18}/>:<Moon size={18}/>}</button>{user?<button className="profileButton" aria-label="进入工作台" onClick={onStudio}>{user.avatarUrl?<img src={user.avatarUrl} alt={user.displayName||user.email}/> : <span>{(user.displayName||user.email||'猫').slice(0,1)}</span>}<i/></button>:<button className="loginButton" onClick={()=>navigate('/login')}>登录</button>}</div><button className="mobileMenu" onClick={()=>setMenuOpen(value=>!value)} aria-label="打开菜单" aria-expanded={menuOpen}><Menu size={20}/></button></div></header>}
function AnimatedCount({value,suffix=''}){const target=Number(value);const isNumber=Number.isFinite(target);const [display,setDisplay]=useState(isNumber?0:null);useEffect(()=>{if(!isNumber){setDisplay(null);return undefined}if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){setDisplay(target);return undefined}let frame=0;const duration=Math.min(1250,500+Math.log10(Math.max(1,target))*190);const started=performance.now();const tick=now=>{const progress=Math.min(1,(now-started)/duration);const eased=1-Math.pow(1-progress,4);setDisplay(Math.round(target*eased));if(progress<1)frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame)},[isNumber,target]);return <b className="statValue">{display===null?'—':display}{suffix}</b>}
function Hero({lightsOn,postCount,siteViewCount,navigate}){return <section className="hero"><div className="heroArt" style={{backgroundImage:`url(${lightsOn?heroLight:heroWorkspace})`}}/><div className="wash"/><div className="wrap heroText"><p className="eyebrow">//　用 AI 解决真实问题</p><h1>让 AI 成为<br/><strong>解决问题的工具</strong></h1><p className="intro">记录用 AI 解决 Linux、网络、运维、开发等<br/>实际问题的过程、思路和经验。<br/>不只是提示词，更关注可落地的方法。</p><div className="stats"><span><AnimatedCount value={postCount}/>AI 实战文章</span><span><AnimatedCount value={50} suffix="+"/>问题场景</span><span><AnimatedCount value={100} suffix="+"/>可复用方案</span><span><AnimatedCount value={siteViewCount}/>站点访问量</span></div><div className="actions"><button onClick={()=>navigate('/categories/ai')}>浏览 AI 解决方案 <Arrow/></button><button onClick={()=>navigate('/posts')}>查看全部文章</button></div></div></section>}
