function NavIcon({name}){return <img className="navIcon" src={iconifyNavIcons[name]||'https://api.iconify.design/tabler:link.svg?color=%23b8c9d9'} alt="" aria-hidden="true"/>}
function CategoryIcon({name}){const variant=name==='Linux'?' is-linux':name==='容器 & 云'?' is-container':'';return <img className={`categoryIcon${variant}`} src={iconifyCategoryIcons[name]||'https://api.iconify.design/tabler:folder.svg?color=%2333c5ef'} alt="" aria-hidden="true"/>}
function SectionIcon({name}){return <img className="sectionIcon" src={iconifySectionIcons[name]} alt="" aria-hidden="true"/>}
function ToolIcon({name}){
  const official=officialBrandIcons[name];
  if(official) return <img className={`officialBrandIcon ${official[1]}`} src={official[0]} alt="" aria-hidden="true"/>;
  if(iconifyToolIcons[name]) return <img className="iconifyToolIcon" src={iconifyToolIcons[name]} alt="" aria-hidden="true"/>;
  const common={viewBox:'0 0 48 48','aria-hidden':'true'};
  return <ImageIcon {...common} strokeWidth="2.45"/>
}
function Categories({categories=[],navigate}){return <section className="categoryArea"><div className="cats">{categories.length?categories.map((item,i)=><button onClick={()=>navigate(`/posts?category=${encodeURIComponent(item.slug)}`)} className={'catCard '+(i?'':'feature')} key={item.id}><CategoryIcon name={item.name}/><b>{item.name}</b><small>{item.postCount} 篇 <Arrow/></small></button>):<p className="dynamicEmpty">暂无分类，导入 Halo 数据或在工作台创建后将在这里显示。</p>}</div></section>}
function Post({p,index,navigate}){const category=p.categories?.[0]||'未分类';const tags=(p.tags||[]).slice(0,3);return <article className="post postLink" tabIndex="0" role="link" onClick={()=>navigate(`/archives/${encodeURIComponent(p.slug)}`)} onKeyDown={event=>event.key==='Enter'&&navigate(`/archives/${encodeURIComponent(p.slug)}`)}><div className={'cover '+['violet','blue','cyan','red','navy','indigo'][index%6]}>{p.coverUrl&&<img className="coverImage" src={p.coverUrl} alt=""/>}<b className="coverBadge">{category}</b>{!p.coverUrl&&<div className="screen"><i/><i/><i/><i/></div>}</div><h2>{p.title}</h2><p>{p.summary||'这篇文章暂未提供摘要。'}</p>{tags.length>0&&<div className="tags">{tags.map(tag=><span key={tag}>{tag}</span>)}</div>}<footer><span><Clock3/> {p.publishedAt?new Date(p.publishedAt).toLocaleDateString('zh-CN'):'草稿'}</span><span><Eye/> {p.viewCount||0}</span><span><MessageSquare/> {p.commentCount||0}</span></footer></article>}
function StatusPanel({statusNodes=[]}){const loopNodes=statusNodes.length>1?[...statusNodes,...statusNodes]:statusNodes;if(!statusNodes.length)return null;return <section className="status"><h3><SectionIcon name="status"/>站点状态 <em><i className="statusPulse" aria-hidden="true"/>正常运行</em></h3><div className="statusNodeViewport"><div className={statusNodes.length>1?'statusNodeTrack isLooping':'statusNodeTrack'}>{loopNodes.map((item,index)=><p key={`${item.id}-${index}`}><i className="statusDot" aria-hidden="true"/>{item.name}<span>{item.latencyMs==null?'待检测':`${item.latencyMs} ms`}</span></p>)}</div></div></section>}
function Side({statusNodes=[],tags=[],tools=[],navigate}){return <aside><StatusPanel statusNodes={statusNodes}/>{tools.length>0&&<section className="panel"><h3><SectionIcon name="tools"/>常用 AI 工具 <a href="/tools" onClick={event=>{event.preventDefault();navigate('/tools')}}>更多工具 <Arrow/></a></h3><div className="tools">{tools.map(item=><a href={item.url} target="_blank" rel="noreferrer" key={item.id}><span className="toolIcon"><ToolIcon name={item.name}/></span><b>{item.name}</b><small>{item.description||'AI 工具'}</small></a>)}</div></section>}{tags.length>0&&<section className="panel tagsPanel"><h3><SectionIcon name="tags"/>热门标签 <a href="/tags" onClick={event=>{event.preventDefault();navigate('/tags')}}>查看全部 <Arrow/></a></h3><div>{tags.map(item=><button onClick={()=>navigate(`/tags/${encodeURIComponent(item.slug)}`)} key={item.id}>{item.name}　{item.postCount}</button>)}</div></section>}<button className="journey" onClick={()=>navigate('/studio')}><Logo iconOnly/><span><b>加入我的旅程</b><small>记录、分享、成长</small></span><Arrow/></button></aside>}
function Main({home,navigate}){const items=home?.posts||[];return <main className="wrap main"><section className="homePrimary"><Categories categories={home?.homeCategories||home?.categories} navigate={navigate}/><div className="heading"><h2><SectionIcon name="latest"/>最新 AI 解决方案</h2><a href="/posts" onClick={event=>{event.preventDefault();navigate('/posts')}}>查看全部 <Arrow/></a></div>{items.length?<div className="posts">{items.map((item,index)=><Post p={item} index={index} navigate={navigate} key={item.id}/>)}</div>:<p className="dynamicEmpty">暂无已发布文章。</p>}<div className="quote"><b>“</b><span>AI 不是替代思考，而是放大解决问题的能力。<small>— 某个晚上</small></span><i>Better Prompts<br/>Bigger Solutions.</i></div></section><Side statusNodes={home?.statusNodes} tags={home?.tags} tools={home?.tools} navigate={navigate}/></main>}
function Footer({navigation=[],navigate}){const footerItems=navigation.filter(item=>item.location==='footer'&&!item.parentId);const follow=(event,item)=>{if(item.openNewTab||!item.url.startsWith('/'))return;event.preventDefault();navigate(item.url)};return <footer><div className="wrap foot"><nav className="footerMenu">{footerItems.length?footerItems.map(item=><a href={item.url} key={item.id} target={item.openNewTab?'_blank':undefined} rel={item.openNewTab?'noopener noreferrer':undefined} onClick={event=>follow(event,item)}>{item.label}</a>):<span>页脚菜单暂未配置</span>}</nav><span className="footerSocial" aria-label="社交链接"><img className="footerGithub" src="https://api.iconify.design/tabler:brand-github.svg?color=%239ab7cb" alt="GitHub"/><Rss/><Mail/><Send/></span></div><div className="wrap copyright"><span>© 2026. All rights reserved.</span><span className="footerBrand"><Logo footer/>记录技术，也记录生活。</span><a className="icpRecord">ICP备案号：待补充</a><span className="footerSlogan">用技术让生活更有趣。</span></div></footer>}
function PublicShell({children,lightsOn,onToggle,navigate,locale,onLocaleToggle}){const [navigation,setNavigation]=useState([]);const [user,setUser]=useState(null);const [showBackToTop,setShowBackToTop]=useState(false);const activeLocale=locale||window.localStorage.getItem('mmcat-locale')||'zh-CN';const toggleLocale=onLocaleToggle||(()=>{window.localStorage.setItem('mmcat-locale',activeLocale==='zh-CN'?'en-US':'zh-CN');window.location.reload()});useEffect(()=>{let active=true;contentApi.navigation(activeLocale).then(result=>{if(active)setNavigation(result.data)}).catch(()=>{});authApi.me().then(result=>active&&setUser(result.data)).catch(()=>active&&setUser(null));return()=>{active=false}},[activeLocale]);useEffect(()=>{const update=()=>setShowBackToTop(window.scrollY>420);update();window.addEventListener('scroll',update,{passive:true});return()=>window.removeEventListener('scroll',update)},[]);return <div className={'appShell '+(lightsOn?'lightsOn':'')}><Header lightsOn={lightsOn} onToggle={onToggle} onStudio={()=>navigate('/studio')} navigate={navigate} navigation={navigation} locale={activeLocale} onLocaleToggle={toggleLocale} user={user}/>{children}<Footer navigation={navigation} navigate={navigate}/><button className={`backToTop${showBackToTop?' isVisible':''}`} onClick={()=>window.scrollTo({top:0,behavior:'smooth'})} aria-label="回到页面顶部" title="回到顶部"><ArrowUp size={20}/></button></div>}
function ListRow({post,navigate}){const date=post.publishedAt?new Date(post.publishedAt):null;const tags=(post.tags||[]).slice(0,3);return <article className="listRow" role="link" tabIndex="0" onClick={()=>navigate(`/archives/${encodeURIComponent(post.slug)}`)} onKeyDown={event=>event.key==='Enter'&&navigate(`/archives/${encodeURIComponent(post.slug)}`)}><time>{date?<><b>{String(date.getMonth()+1).padStart(2,'0')}-{String(date.getDate()).padStart(2,'0')}</b><span>{date.getFullYear()}</span></>:<b>草稿</b>}</time><div className="listCopy"><h2>{post.title}</h2><p>{post.summary||'这篇文章暂未提供摘要。'}</p><div className="listRowMeta">{tags.map(tag=><span key={tag}>{tag}</span>)}<em className="listMetrics"><Eye size={14}/>{post.viewCount||0}</em><em className="listMetrics"><MessageSquare size={14}/>{post.commentCount||0}</em></div></div>{post.coverUrl?<img src={post.coverUrl} alt=""/>:<div className="listNoCover"><FileText size={24}/></div>}</article>}
function PublicSidebar({home,navigate}){return <aside className="publicSidebar">{(home?.statusNodes||[]).length>0&&<section className="sidebarStatus"><h3><SectionIcon name="status"/>当前状态 <em><i/>全部正常</em></h3>{home.statusNodes.map(item=><p key={item.id}><i/>{item.name}<small>{item.latencyMs==null?'—':`${item.latencyMs} ms`}</small></p>)}</section>}<section><h3>正在探索</h3><div className="exploreLinks">{(home?.categories||[]).map(item=><button key={item.id} onClick={()=>navigate(`/posts?category=${encodeURIComponent(item.slug)}`)}>→　{item.name}<small>{item.postCount}</small></button>)}</div></section><section><h3>热门标签</h3><div className="sidebarTags">{(home?.tags||[]).slice(0,14).map(item=><button key={item.id} onClick={()=>navigate(`/posts?tag=${encodeURIComponent(item.slug)}`)}>{item.name}<small>{item.postCount}</small></button>)}</div></section><section className="sidebarQuote"><b>“</b><p>把复杂的问题，拆成每一次可验证的实践。<small>— 猫子</small></p></section></aside>}
function PostListScreen({lightsOn,onToggle,navigate,site}){const params=new URLSearchParams(window.location.search);const path=window.location.pathname;const q=params.get('q')||'';const category=path.startsWith('/categories/')?decodeURIComponent(path.slice('/categories/'.length)):(params.get('category')||'');const tag=path.startsWith('/tags/')?decodeURIComponent(path.slice('/tags/'.length)):(params.get('tag')||'');const page=Math.max(1,Number(params.get('page'))||1);const pageSize=String(category?(site?.categoryPostsPerPage||12):tag?(site?.tagPostsPerPage||12):(site?.postsPerPage||12));const [state,setState]=useState({loading:true,items:[],total:0,totalPages:0,error:''});const [home,setHome]=useState(null);useEffect(()=>{let active=true;setState(value=>({...value,loading:true,error:''}));Promise.all([contentApi.posts({q,category,tag,page,pageSize}),contentApi.home()]).then(([posts,homepage])=>{if(!active)return;setState({loading:false,items:posts.data,total:posts.meta?.total||0,totalPages:posts.meta?.totalPages||0,error:''});setHome(homepage.data)}).catch(error=>active&&setState({loading:false,items:[],total:0,totalPages:0,error:error.message||'文章列表加载失败。'}));return()=>{active=false}},[q,category,tag,page,pageSize]);const categoryName=home?.categories?.find(item=>item.slug===category)?.name;const tagName=home?.tags?.find(item=>item.slug===tag)?.name;const title=q?`搜索：${q}`:category?(categoryName||'分类文章'):tag?(tagName||'标签文章'):'最新文章';const goPage=target=>{const next=new URLSearchParams();if(q)next.set('q',q);if(target>1)next.set('page',String(target));const base=category?`/categories/${encodeURIComponent(category)}`:tag?`/tags/${encodeURIComponent(tag)}`:'/posts';navigate(`${base}${next.size?`?${next}`:''}`)};const pages=Array.from({length:state.totalPages},(_,index)=>index+1).filter(value=>value===1||value===state.totalPages||Math.abs(value-page)<=1);return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap listingPage"><header className="listingHead"><h1>{title}</h1><span>共记录 {state.total || '—'} 篇内容，以问题、过程和可复用方案为线索。</span></header><div className="listingLayout"><section className="articleList">{state.error?<p className="dynamicError">{state.error}</p>:state.loading?<p className="dynamicEmpty">正在加载文章…</p>:state.items.length?<>{state.items.map(item=><ListRow post={item} navigate={navigate} key={item.id}/>)}{state.totalPages>1&&<nav className="listingPagination" aria-label="文章分页"><button disabled={page===1} onClick={()=>goPage(page-1)}>上一页</button>{pages.map((value,index)=><React.Fragment key={value}>{index>0&&value-pages[index-1]>1&&<i>…</i>}<button className={value===page?'active':''} onClick={()=>goPage(value)}>{value}</button></React.Fragment>)}<button disabled={page===state.totalPages} onClick={()=>goPage(page+1)}>下一页</button></nav>}</>:<p className="dynamicEmpty">没有匹配的已发布文章。</p>}</section><PublicSidebar home={home} navigate={navigate}/></div></main></PublicShell>}
function contentText(value){const text=typeof value==='string'?value:value==null?'':(()=>{try{return JSON.stringify(value)}catch{return ''}})();return text.replace(/^(!\[[^\]]*\]\([^\n)]+\))\s*(.+)$/gm,'$1\n$2')}
function legacyHaloText(content){const source=contentText(content);try{const patches=JSON.parse(source);if(!Array.isArray(patches))return source;const html=patches.map(item=>item?.target?.lines?.join('\n')||'').join('\n');return new DOMParser().parseFromString(html,'text/html').body.textContent?.trim()||source}catch{return source}}
function InlineMarkdown({value}){const parts=value.split(/(\[[^\]]+\]\([^\s)]+\)|`[^`]+`|\*\*[^*]+\*\*)/g);return <>{parts.map((part,index)=>{const link=part.match(/^\[([^\]]+)\]\(([^\s)]+)\)$/);if(link){const safe=/^https?:\/\//i.test(link[2]);return safe?<a key={index} href={link[2]} target="_blank" rel="noreferrer">{link[1]}</a>:link[1]}if(part.startsWith('`')&&part.endsWith('`'))return <code key={index}>{part.slice(1,-1)}</code>;if(part.startsWith('**')&&part.endsWith('**'))return <strong key={index}>{part.slice(2,-2)}</strong>;return part})}</>}
function articleHeadings(content){return contentText(content).replace(/\r\n/g,'\n').split('\n').map(line=>line.match(/^(#{1,6})\s+(.+)/)).filter(Boolean).slice(0,40).map((match,index)=>({id:`section-${index}`,depth:Math.min(match[1].length,6),title:match[2].replace(/[*_`]/g,'').trim()}))}
function htmlHeadings(content){const document=new DOMParser().parseFromString(contentText(content),'text/html');return [...document.querySelectorAll('h2,h3,h4,h5,h6')].slice(0,40).map((node,index)=>({id:`section-${index}`,depth:Number(node.tagName.slice(1))-1,title:(node.textContent||'').trim()})).filter(item=>item.title)}
function ArticleToc({headings}){const baseDepth=Math.min(...headings.map(item=>item.depth));return <nav className="articleToc" aria-label="文章目录">{headings.map(entry=>{const level=Math.max(0,entry.depth-baseDepth);return <a className={`depth-${Math.min(entry.depth,6)}`} style={{'--toc-depth':level}} href={`#${entry.id}`} key={entry.id} aria-level={level+1}>{entry.title}</a>})}</nav>}
function tableCells(line){return line.trim().replace(/^\||\|$/g,'').split('|').map(cell=>cell.trim().replace(/\\\|/g,'|'))}
function isTableDivider(line){return tableCells(line).every(cell=>/^:?-{3,}:?$/.test(cell))}
function HighlightedCode({code,language}){const selected=language&&hljs.getLanguage(language)?hljs.highlight(code,{language}).value:hljs.highlightAuto(code).value;return <pre><code className="hljs" dangerouslySetInnerHTML={{__html:selected}}/></pre>}
function MarkdownBody({content,headings=[]}){const lines=contentText(content).replace(/\r\n/g,'\n').split('\n');const blocks=[];let index=0;let headingIndex=0;while(index<lines.length){const line=lines[index];if(!line.trim()){index+=1;continue}if(/^```/.test(line.trim())){const language=line.trim().slice(3).trim();const code=[];index+=1;while(index<lines.length&&!/^```/.test(lines[index].trim())){code.push(lines[index]);index+=1}index+=1;blocks.push(<HighlightedCode key={`code-${index}`} code={code.join('\n')} language={language}/>);continue}const heading=line.match(/^(#{1,6})\s+(.+)/);if(heading){const Tag=`h${Math.min(heading[1].length+1,4)}`;const headingId=headings[headingIndex++]?.id;blocks.push(<Tag id={headingId} key={`heading-${index}`}><InlineMarkdown value={heading[2]}/></Tag>);index+=1;continue}if(line.includes('|')&&index+1<lines.length&&isTableDivider(lines[index+1])){const headers=tableCells(line);const rows=[];index+=2;while(index<lines.length&&lines[index].includes('|')&&lines[index].trim()){rows.push(tableCells(lines[index]));index+=1}blocks.push(<div className="articleTableWrap" key={`table-${index}`}><table><thead><tr>{headers.map((cell,column)=><th key={column}><InlineMarkdown value={cell}/></th>)}</tr></thead><tbody>{rows.map((row,rowIndex)=><tr key={rowIndex}>{headers.map((_,column)=><td key={column}><InlineMarkdown value={row[column]||''}/></td>)}</tr>)}</tbody></table></div>);continue}const image=line.match(/^!\[([^\]]*)\]\(([^\s)]+)\)$/);if(image){blocks.push(<img className="articleInlineImage" key={`image-${index}`} src={image[2]} alt={image[1]||''}/>);index+=1;continue}if(/^[-*]\s+/.test(line)){const items=[];while(index<lines.length&&/^[-*]\s+/.test(lines[index])){items.push(<li key={index}><InlineMarkdown value={lines[index].replace(/^[-*]\s+/, '')}/></li>);index+=1}blocks.push(<ul key={`list-${index}`}>{items}</ul>);continue}const paragraph=[];while(index<lines.length&&lines[index].trim()&&!/^```/.test(lines[index].trim())&&!/^(#{1,6})\s+/.test(lines[index])&&!/^!\[/.test(lines[index])&&!/^[-*]\s+/.test(lines[index])){paragraph.push(lines[index]);index+=1}blocks.push(<p key={`paragraph-${index}`}><InlineMarkdown value={paragraph.join(' ')}/></p>)}return <div className="articleBody">{blocks}</div>}
function sanitizedHtml(content,headings=[]){const document=new DOMParser().parseFromString(contentText(content),'text/html');const tags=new Set(['p','br','h2','h3','h4','h5','h6','ul','ol','li','strong','em','b','i','code','pre','blockquote','a','img','table','thead','tbody','tr','th','td','hr']);const safeUrl=(value,allowMail=false)=>{if(value.startsWith('/')&&!value.startsWith('//')||value.startsWith('#'))return true;try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)||(allowMail&&url.protocol==='mailto:')}catch{return false}};[...document.querySelectorAll('h2,h3,h4,h5,h6')].forEach((node,index)=>{if(headings[index])node.id=headings[index].id});[...document.body.querySelectorAll('*')].forEach(node=>{if(!tags.has(node.tagName.toLowerCase())){node.replaceWith(...node.childNodes);return}for(const attribute of [...node.attributes]){const name=attribute.name.toLowerCase();const value=attribute.value.trim();const allowed=(node.tagName==='A'&&['href','title'].includes(name))||(node.tagName==='IMG'&&['src','alt','title','width','height'].includes(name))||(/^H[2-6]$/.test(node.tagName)&&name==='id')||(['TH','TD'].includes(node.tagName)&&['colspan','rowspan'].includes(name));if(!allowed||((name==='href'&&!safeUrl(value,true))||(name==='src'&&!safeUrl(value))))node.removeAttribute(attribute.name)}if(node.tagName==='A'&&node.getAttribute('target')==='_blank')node.setAttribute('rel','noopener noreferrer')});return document.body.innerHTML}
function HtmlBody({content,headings=[]}){return <div className="articleBody htmlArticleBody" dangerouslySetInnerHTML={{__html:sanitizedHtml(content,headings)}}/>}
function commentThreadCount(comment){return 1+(comment.replies||[]).reduce((total,reply)=>total+commentThreadCount(reply),0)}
function CommentThread({comment,depth=0}){return <article className="commentItem" data-depth={depth}><div className="commentAvatar" aria-hidden="true">{(comment.authorName||'访').slice(0,1)}</div><div className="commentContent"><div className="commentItemMeta"><strong>{comment.authorName}</strong><time>{new Date(comment.ctime).toLocaleString('zh-CN')}</time></div><p>{comment.content}</p>{comment.replies?.length>0&&<div className="commentChildren">{comment.replies.map(reply=><CommentThread comment={reply} depth={depth+1} key={reply.id}/>)}</div>}</div></article>}
function ArticleComments({postId,navigate,onApprovedCount}){const [comments,setComments]=useState([]);const [user,setUser]=useState(null);const [content,setContent]=useState('');const [emojiOpen,setEmojiOpen]=useState(false);const [status,setStatus]=useState({loading:true,message:'',posting:false});const emoji=['😀','😂','😊','😍','🤔','😅','😭','😎','👍','👎','👏','🎉','🔥','❤️','✨','🐱'];const displayedCount=comments.reduce((total,comment)=>total+commentThreadCount(comment),0);const countResult=result=>(result.data||[]).reduce((total,comment)=>total+commentThreadCount(comment),0);const load=useCallback(()=>contentApi.comments({postId,pageSize:100}).then(result=>{setComments(result.data||[]);onApprovedCount?.(countResult(result))}).catch(error=>setStatus(value=>({...value,message:error.message||'评论加载失败。'}))),[postId,onApprovedCount]);useEffect(()=>{let active=true;setStatus({loading:true,message:'',posting:false});Promise.all([contentApi.comments({postId,pageSize:100}),authApi.me().catch(()=>null)]).then(([result,profile])=>{if(!active)return;setComments(result.data||[]);onApprovedCount?.(countResult(result));setUser(profile?.data||null);setStatus({loading:false,message:'',posting:false})}).catch(error=>active&&setStatus({loading:false,message:error.message||'评论加载失败。',posting:false}));return()=>{active=false}},[postId,onApprovedCount]);const submit=async event=>{event.preventDefault();const text=content.trim();if(!text)return;setStatus(value=>({...value,posting:true,message:''}));try{await contentApi.createComment({targetType:'post',targetId:postId,content:text});setContent('');setEmojiOpen(false);setStatus({loading:false,posting:false,message:'评论已提交，审核通过后会显示在这里。'});load()}catch(error){setStatus(value=>({...value,posting:false,message:error.message||'评论发送失败。'}))}};return <section className="articleComments" aria-label="评论"><div className="articleCommentsHead"><h2>评论</h2><span>{displayedCount} 条已发布评论</span></div>{status.loading?<p className="commentEmpty">正在加载评论…</p>:comments.length?<div className="commentList">{comments.map(comment=><CommentThread comment={comment} key={comment.id}/>)}</div>:<p className="commentEmpty">还没有评论，来说两句吧。</p>}{user?<form className="commentForm" onSubmit={submit}><label htmlFor="article-comment">发表评论</label><textarea id="article-comment" value={content} onChange={event=>setContent(event.target.value)} maxLength="5000" placeholder="写下你的想法…"/><div className="commentActions"><div className="emojiPicker"><button type="button" className="emojiTrigger" onClick={()=>setEmojiOpen(value=>!value)} aria-label="插入表情" aria-expanded={emojiOpen}><Smile size={17}/> 表情</button>{emojiOpen&&<div className="emojiPanel">{emoji.map(item=><button type="button" key={item} onClick={()=>{setContent(value=>`${value}${item}`);setEmojiOpen(false)}} aria-label={`插入${item}`}>{item}</button>)}</div>}</div><small>评论需要审核后才会公开显示。</small><button type="submit" disabled={status.posting}>{status.posting?'发送中…':'发表评论'} <Send size={14}/></button></div></form>:<div className="commentLogin"><span>登录并验证邮箱后可以发表评论。</span><button onClick={()=>navigate(`/login?next=${encodeURIComponent(window.location.pathname)}`)}>登录后评论</button></div>}{status.message&&<p className="commentNotice">{status.message}</p>}</section>}

function ArticleScreen({slug,lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,item:null,error:''});const [home,setHome]=useState(null);const [commentCount,setCommentCount]=useState(0);useEffect(()=>{let active=true;Promise.all([contentApi.post(slug),contentApi.home()]).then(([post,homepage])=>active&&((setState({loading:false,item:post.data,error:''})),setCommentCount(post.data.commentCount||0),setHome(homepage.data))).catch(error=>active&&setState({loading:false,item:null,error:error.message||'文章加载失败。'}));return()=>{active=false}},[slug]);const item=state.item;const isHtml=item?.contentFormat==='html';const body=item?(isHtml?contentText(item.content||''):legacyHaloText(item.content||'')):'';const headings=isHtml?htmlHeadings(body):articleHeadings(body);const date=item?.publishedAt?new Date(item.publishedAt).toLocaleDateString('zh-CN'):'草稿';return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap articlePage">{state.loading?<p className="dynamicEmpty">正在加载文章…</p>:state.error?<><button className="backButton" onClick={()=>navigate('/posts')}>← 返回文章列表</button><p className="dynamicError">{state.error}</p></>:<div className="articleLayout"><aside className="articleLeftRail"><h3>分类</h3>{(home?.categories||[]).map(category=><button key={category.id} onClick={()=>navigate(`/categories/${encodeURIComponent(category.slug)}`)}><CategoryIcon name={category.name}/><span>{category.name}</span><small>{category.postCount}</small></button>)}</aside><article className="articleDocument"><button className="backButton" onClick={()=>navigate('/posts')}>← 返回文章列表</button><h1>{item.title}</h1><div className="articleMeta articleMetrics"><span><Clock3/> {date}</span><span><Eye/> {item.viewCount||0}</span><span><MessageSquare/> {commentCount}</span></div><div className="articleTaxonomy">{(item.categories||[]).map(category=><button className="categoryPill" key={category.slug} onClick={()=>navigate(`/categories/${encodeURIComponent(category.slug)}`)}>分类：{category.name}</button>)}{(item.tags||[]).map(tag=><button className="tagPill" key={tag.slug} onClick={()=>navigate(`/tags/${encodeURIComponent(tag.slug)}`)}>#{tag.name}</button>)}</div>{item.coverUrl&&<img className="articleCover" src={item.coverUrl} alt=""/>}{isHtml?<HtmlBody content={body} headings={headings}/>:<MarkdownBody content={body} headings={headings}/>}<ArticleComments postId={item.id} navigate={navigate} onApprovedCount={setCommentCount}/></article><aside className="articleRightRail"><section><h3>目录</h3>{headings.length?<ArticleToc headings={headings}/>:<p>本文暂无目录。</p>}</section><section><h3>热门标签</h3><div className="sidebarTags">{(home?.tags||[]).slice(0,10).map(tag=><button key={tag.id} onClick={()=>navigate(`/tags/${encodeURIComponent(tag.slug)}`)}>{tag.name}<small>{tag.postCount}</small></button>)}</div></section></aside></div>}</main></PublicShell>}
function PageScreen({slug,lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,item:null,error:''});useEffect(()=>{contentApi.page(slug).then(result=>setState({loading:false,item:result.data,error:''})).catch(error=>setState({loading:false,item:null,error:error.message||'页面加载失败。'}))},[slug]);const item=state.item;return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap articlePage"><article className="articleDocument">{state.loading?<p className="dynamicEmpty">正在加载页面…</p>:state.error?<p className="dynamicError">{state.error}</p>:<><h1>{item.title}</h1>{item.contentFormat==='html'?<HtmlBody content={item.content}/>:<MarkdownBody content={item.content}/>}</>}</article></main></PublicShell>}
function TagsScreen({lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,items:[],error:''});useEffect(()=>{let active=true;contentApi.tags().then(result=>active&&setState({loading:false,items:result.data||[],error:''})).catch(error=>active&&setState({loading:false,items:[],error:error.message||'标签加载失败。'}));return()=>{active=false}},[]);return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap tagIndexPage"><header><p className="eyebrow">TOPICS</p><h1>标签</h1><span>按主题浏览文章与实践记录。</span></header>{state.loading?<p className="dynamicEmpty">正在加载标签…</p>:state.error?<p className="dynamicError">{state.error}</p>:state.items.length?<section className="tagIndexCloud" aria-label="全部标签">{state.items.map(tag=><button key={tag.id} onClick={()=>navigate(`/tags/${encodeURIComponent(tag.slug)}`)}><b># {tag.name}</b><small>{tag.postCount}</small></button>)}</section>:<p className="dynamicEmpty">暂无标签。</p>}</main></PublicShell>}
function ToolsScreen({lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,items:[],error:''});useEffect(()=>{let active=true;contentApi.tools().then(result=>active&&setState({loading:false,items:result.data||[],error:''})).catch(error=>active&&setState({loading:false,items:[],error:error.message||'AI 工具加载失败。'}));return()=>{active=false}},[]);const groups=state.items.reduce((all,item)=>{const name=item.category||'其他工具';(all[name]||=[]).push(item);return all},{});return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap toolsPage"><header><p className="eyebrow">TOOLBOX</p><h1>AI 工具</h1><span>精选的 AI 产品与实用服务，点击即可前往官方网站。</span></header>{state.loading?<p className="dynamicEmpty">正在加载 AI 工具…</p>:state.error?<p className="dynamicError">{state.error}</p>:Object.keys(groups).length?<div className="toolDirectory">{Object.entries(groups).map(([category,items])=><section key={category}><h2>{category}<small>{items.length} 个工具</small></h2><div>{items.map(item=><a href={item.url} target="_blank" rel="noopener noreferrer" key={item.id}><span><ToolIcon name={item.name}/></span><article><b>{item.name}</b><p>{item.description||'访问官方网站了解更多。'}</p>{item.provider&&<small>{item.provider}</small>}</article><ArrowRight size={18}/></a>)}</div></section>)}</div>:<p className="dynamicEmpty">暂无 AI 工具。</p>}</main></PublicShell>}
function FriendLinksScreen({lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,items:[],error:''});useEffect(()=>{contentApi.friendLinks().then(result=>setState({loading:false,items:result.data||[],error:''})).catch(error=>setState({loading:false,items:[],error:error.message||'友情链接加载失败。'}))},[]);return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap listingPage friendLinksPage"><header className="listingHead"><h1>友情链接</h1><span>与值得关注的朋友保持连接。</span></header>{state.loading?<p className="dynamicEmpty">正在加载…</p>:state.error?<p className="dynamicError">{state.error}</p>:<section className="friendLinksGrid">{state.items.map(item=><a className="friendLinkCard" href={item.url} target={item.target} rel={item.rel||'noopener noreferrer'} key={item.id}>{item.logoUrl?<img src={item.logoUrl} alt={`${item.name} 图标`}/>:<div className="friendLinkAvatar" aria-hidden="true"><Globe2/></div>}<div><h2>{item.name}</h2><p>{item.description||item.url}</p></div><ArrowRight className="friendLinkArrow" size={18} aria-hidden="true"/></a>)}</section>}</main></PublicShell>}
function GalleriesScreen({lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,items:[],error:''});useEffect(()=>{let active=true;contentApi.galleries().then(result=>{if(!active)return;const items=result.data||[];if(items.length===1){navigate(`/photos/${encodeURIComponent(items[0].slug)}`);return;}setState({loading:false,items,error:''});}).catch(error=>active&&setState({loading:false,items:[],error:error.message||'图库加载失败。'}));return()=>{active=false};},[navigate]);return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="wrap listingPage"><header className="listingHead"><h1>图库</h1><span>记录值得保存的瞬间。</span></header>{state.loading?<p className="dynamicEmpty">正在加载…</p>:state.error?<p className="dynamicError">{state.error}</p>:<section className="articleList">{state.items.map(item=><button className="listRow" onClick={()=>navigate(`/photos/${encodeURIComponent(item.slug)}`)} key={item.id}>{item.coverUrl?<img src={item.coverUrl} alt=""/>:<div className="listNoCover"><ImageIcon/></div>}<div className="listCopy"><h2>{item.name}</h2><p>{item.description||`${item.itemCount} 个媒体文件`}</p></div></button>)}</section>}</main></PublicShell>}
function GalleryLightbox({items,index,onClose,onChange,hasMore}){const item=items[index];const canGoPrevious=index>0;const canGoNext=index<items.length-1||hasMore;return <div role="dialog" aria-modal="true" aria-label="图片预览" style={{position:'fixed',inset:0,zIndex:100,display:'grid',gridTemplateColumns:'auto minmax(0,1fr) auto',alignItems:'center',gap:16,padding:24,background:'rgba(4,12,19,.92)'}}><button onClick={onClose} aria-label="关闭预览" style={{position:'absolute',top:20,right:24,border:0,borderRadius:8,background:'rgba(255,255,255,.14)',color:'#fff',fontSize:28,lineHeight:1,padding:'6px 11px',cursor:'pointer'}}>×</button><button onClick={()=>onChange(index-1)} disabled={!canGoPrevious} aria-label="上一张" style={{border:0,background:'transparent',color:'#fff',fontSize:54,cursor:canGoPrevious?'pointer':'default',opacity:canGoPrevious?1:.25}}>‹</button><figure style={{display:'grid',justifyItems:'center',gap:12,maxWidth:'100%',maxHeight:'100%',margin:0}}><img src={item.url} alt={item.alt||item.name||''} style={{display:'block',maxWidth:'100%',maxHeight:'calc(100vh - 108px)',objectFit:'contain'}}/><figcaption style={{color:'#fff',fontSize:14}}>{item.title||item.name||`${index+1} / ${items.length}`}</figcaption></figure><button onClick={()=>onChange(index+1)} disabled={!canGoNext} aria-label="下一张" style={{border:0,background:'transparent',color:'#fff',fontSize:54,cursor:canGoNext?'pointer':'default',opacity:canGoNext?1:.25}}>›</button></div>}
function GalleryScreen({slug,lightsOn,onToggle,navigate}){const [state,setState]=useState({loading:true,item:null,items:[],page:0,total:0,hasMore:false,loadingMore:false,error:''});const [lightboxIndex,setLightboxIndex]=useState(null);const loadPage=useCallback(async(page,append)=>{setState(value=>({...value,loading:!append,loadingMore:append,error:''}));try{const result=await contentApi.gallery(slug,{page,page_size:24});const nextItems=result.data.items||[];const meta=result.meta||{};setState(value=>({loading:false,item:result.data,items:append?[...value.items,...nextItems]:nextItems,page:Number(meta.page)||page,total:Number(meta.total)||nextItems.length,hasMore:(Number(meta.page)||page)<(Number(meta.totalPages)||1),loadingMore:false,error:''}));return nextItems.length;}catch(error){setState(value=>({...value,loading:false,loadingMore:false,error:error.message||'图库加载失败。'}));return 0;}},[slug]);useEffect(()=>{setLightboxIndex(null);loadPage(1,false);},[loadPage]);const loadMore=useCallback(()=>{if(state.loading||state.loadingMore||!state.hasMore)return Promise.resolve(0);return loadPage(state.page+1,true);},[loadPage,state.hasMore,state.loading,state.loadingMore,state.page]);const loadMoreRef=useRef(null);loadMoreRef.current=loadMore;const sentinelRef=useRef(null);useEffect(()=>{const sentinel=sentinelRef.current;if(!sentinel||!state.hasMore||typeof IntersectionObserver==='undefined')return;const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting))loadMoreRef.current?.();},{rootMargin:'600px 0px'});observer.observe(sentinel);return()=>observer.disconnect();},[state.hasMore]);const changeLightbox=async next=>{if(next<0)return;if(next<state.items.length){setLightboxIndex(next);return;}if(state.hasMore&&(await loadMore())>0)setLightboxIndex(next);};return <PublicShell lightsOn={lightsOn} onToggle={onToggle} navigate={navigate}><main className="photoGalleryPage">{state.loading?<p className="dynamicEmpty">正在加载…</p>:state.error?<p className="dynamicError">{state.error}</p>:<><section className="photoWall" aria-label={`${state.item.name}图片列表`}>{state.items.map((item,index)=><button type="button" className="photoTile" onClick={()=>setLightboxIndex(index)} key={item.id}>{item.mimeType?.startsWith('image/')?<img src={item.url} alt={item.alt||item.title||item.name||''} loading="lazy" decoding="async"/>:<span className="photoTileFallback"><ImageIcon size={32}/></span>}<b>{item.title||item.name}</b></button>)}</section>{!state.items.length&&<p className="dynamicEmpty">这个图库还没有图片。</p>}{state.hasMore&&<div className="photoWallSentinel" ref={sentinelRef} aria-live="polite">{state.loadingMore?'正在加载更多图片…':'继续向下滚动加载更多图片'}</div>}{lightboxIndex!==null&&<GalleryLightbox items={state.items} index={lightboxIndex} hasMore={state.hasMore} onClose={()=>setLightboxIndex(null)} onChange={changeLightbox}/>}</>}</main></PublicShell>}
function App(){const [lightsOn,setLightsOn]=useState(false);const [location,setLocation]=useState(()=>window.location.pathname+window.location.search);const [home,setHome]=useState(null);const [homeError,setHomeError]=useState('');const [site,setSite]=useState(null);const navigate=useCallback((to)=>{let target=to||'/';target=target.replace(/^\/posts\?category=([^&]+)$/, '/categories/$1').replace(/^\/posts\?tag=([^&]+)$/, '/tags/$1');if(window.location.pathname+window.location.search!==target)window.history.pushState({},'',target);setLocation(target);window.scrollTo({top:0,behavior:'auto'});},[]);useEffect(()=>{const update=()=>setLocation(window.location.pathname+window.location.search);window.addEventListener('popstate',update);return()=>window.removeEventListener('popstate',update);},[]);useEffect(()=>{let active=true;contentApi.home().then((result)=>active&&setHome(result.data)).catch(()=>active&&setHomeError('首页数据暂时无法加载。'));contentApi.site().then(result=>active&&setSite(result.data)).catch(()=>{});return()=>{active=false};},[]);useEffect(()=>{if(!site)return;document.title=site.siteName||document.title;const description=document.querySelector('meta[name="description"]')||Object.assign(document.createElement('meta'),{name:'description'});description.content=site.siteDescription||'';if(!description.parentNode)document.head.appendChild(description);let robots=document.querySelector('meta[name="robots"]');if(site.seoNoindex){robots=robots||Object.assign(document.createElement('meta'),{name:'robots'});robots.content='noindex,nofollow';if(!robots.parentNode)document.head.appendChild(robots);}else if(robots){robots.remove();}let keywords=document.querySelector('meta[name="keywords"]');if(site.siteKeywords){keywords=keywords||Object.assign(document.createElement('meta'),{name:'keywords'});keywords.content=site.siteKeywords;if(!keywords.parentNode)document.head.appendChild(keywords);}else if(keywords){keywords.remove();}},[site]);const pathname=location.split('?')[0];if(pathname==='/login')return <AuthScreen mode="login" navigate={navigate} location={location}/>;if(pathname==='/register')return <AuthScreen mode="register" navigate={navigate} location={location}/>;if(pathname==='/verify-email')return <VerifyEmailScreen navigate={navigate} location={location}/>;if(pathname==='/studio'||pathname.startsWith('/studio/'))return <React.Suspense fallback={<main className="studioLoading">正在加载工作台…</main>}><StudioApp navigate={navigate} location={location}/></React.Suspense>;if(pathname==='/links')return <FriendLinksScreen lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;if(pathname==='/tools')return <ToolsScreen lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;if(pathname==='/tags')return <TagsScreen lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;if(pathname==='/photos')return <GalleriesScreen lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;if(pathname.startsWith('/photos/'))return <GalleryScreen slug={decodeURIComponent(pathname.slice('/photos/'.length))} lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;if(pathname==='/posts'||pathname.startsWith('/categories/')||pathname.startsWith('/tags/'))return <PostListScreen lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate} site={site}/>;if(pathname.startsWith('/archives/'))return <ArticleScreen slug={decodeURIComponent(pathname.slice('/archives/'.length))} lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;if(/^\/[^/]+$/.test(pathname))return <PageScreen slug={decodeURIComponent(pathname.slice(1))} lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}/>;return <PublicShell lightsOn={lightsOn} onToggle={()=>setLightsOn(value=>!value)} navigate={navigate}><Hero lightsOn={lightsOn} postCount={home?.postCount} siteViewCount={home?.siteViewCount} navigate={navigate}/>{homeError&&<p className="wrap dynamicError">{homeError}</p>}<Main home={home} navigate={navigate}/></PublicShell>}
createRoot(document.getElementById('root')).render(<App/>);
